part1 = 'import os\nimport json\nimport logging\nimport sqlite3\nimport hashlib\nfrom datetime import datetime\n\nclass HarvestScanner:\n    def __init__(self, root_dir, db_path=\'harvest.db\', log_path=\'harvest.log\'):\n        self.root_dir = os.path.abspath(root_dir)\n        self.db_path = db_path\n        self.log_path = log_path\n        self._setup_logging()\n        self._init_db()\n\n    def _setup_logging(self):\n        logging.basicConfig(\n            filename=self.log_path,\n            level=logging.INFO,\n            format=\'%(asctime)s - %(levelname)s - %(message)s\',\n            encoding=\'utf-8\'\n        )\n        self.logger = logging.getLogger(\'HarvestScanner\')\n\n    def _init_db(self):\n        with sqlite3.connect(self.db_path) as conn:\n            conn.execute(\'\'\'\n                CREATE TABLE IF NOT EXISTS harvest_entries (\n                    id INTEGER PRIMARY KEY AUTOINCREMENT,\n                    file_path TEXT UNIQUE,\n                    last_seen TIMESTAMP,\n                    hash TEXT\n                )\n            \'\'\')\n\n    def _get_file_hash(self, filepath):\n        sha256_hash = hashlib.sha256()\n        try:\n            with open(filepath, "rb") as f:\n                for byte_block in iter(lambda: f.read(4096), b""):\n                    sha256_hash.update(byte_block)\n            return sha256_hash.hexdigest()\n        except Exception as e:\n            self.logger.error(f"Error hashing {filepath}: {e}")\n            return None\n\n    def scan(self):\n        self.logger.info(f"Scan started in {self.root_dir}")\n        stats = {"new": 0, "changed": 0, "unchanged": 0, "total": 0}\n        found_files = []\n\n        with sqlite3.connect(self.db_path) as conn:\n            conn.row_factory = sqlite3.Row\n            cursor = conn.cursor()\n            \n            cursor.execute("SELECT file_path, hash FROM harvest_entries")\n            db_state = {row[\'file_path\']: row[\'hash\'] for row in cursor.fetchall()}\n\n            for root, _, files in os.walk(self.root_dir):\n                for file in files:\n                    if file.endswith((\'.py\', \'.md\', \'.json\', \'.txt\', \'.bat\', \'.ps1\')):\n                        full_path = os.path.normpath(os.path.join(root, file))\n                        found_files.append(full_path)\n                        stats["total"] += 1\n                        \n                        current_hash = self._get_file_hash(full_path)\n                        if not current_hash:\n                            continue\n\n                        now = datetime.now().isoformat()\n\n                        if full_path not in db_state:\n                            cursor.execute(\'\'\'\n                                INSERT INTO harvest_entries (file_path, last_seen, hash)\n                                VALUES (?, ?, ?)\n                            \'\'\', (full_path, now, current_hash))\n                            stats["new"] += 1\n                            self.logger.info(f"NEW: {full_path}")\n                        elif db_state[full_path] != current_hash:\n                            cursor.execute(\'\'\'\n                                UPDATE harvest_entries \n                                SET last_seen = ?, hash = ? \n                                WHERE file_path = ?\n                            \'\'\', (now, current_hash, full_path))\n                            stats["changed"] += 1\n                            self.logger.info(f"CHANGED: {full_path}")\n                        else:\n                            cursor.execute(\'\'\'\n                                UPDATE harvest_entries SET last_seen = ? WHERE file_path = ?\n                            \'\'\', (now, full_path))\n                            stats["unchanged"] += 1\n            \n            conn.commit()\n\n        self._write_artifacts(stats, found_files)\n        self.logger.info(f"Scan finished. Stats: {stats}")\n        return stats\n\n    def _write_artifacts(self, stats, files):\n        with open("last_harvest.json", "w", encoding="utf-8") as f:\n            json.dump({\n                "timestamp": datetime.now().isoformat(),\n                "stats": stats,\n                "files_count": len(files)\n            }, f, indent=4, ensure_ascii=False)\n'
part2 = '\nif __name__ == "__main__":\n    import shutil\n    test_dir = "harvest_test_env"\n    if os.path.exists(test_dir):\n        shutil.rmtree(test_dir)\n    os.makedirs(test_dir)\n    \n    with open(os.path.join(test_dir, "a.py"), "w") as f: f.write("print(\'a\')")\n    with open(os.path.join(test_dir, "b.md"), "w") as f: f.write("# b")\n    \n    print("--- First Run (Initial) ---")\n    scanner = HarvestScanner(test_dir, db_path="test_harvest.db", log_path="test_harvest.log")\n    res1 = scanner.scan()\n    print(f"Stats: {res1}")\n    \n    print("\\n--- Second Run (Changes) ---")\n    with open(os.path.join(test_dir, "a.py"), "w") as f: f.write("print(\'a_mod\')")\n    with open(os.path.join(test_dir, "c.txt"), "w") as f: f.write("new file")\n    \n    res2 = scanner.scan()\n    print(f"Stats: {res2}")\n    \n    print("\\n--- Artifact Verification ---")\n    if os.path.exists("last_harvest.json"):\n        with open("last_harvest.json", "r") as f:\n            print(f"last_harvest.json: {f.read()}")\n            \n    print("\\nCleaning up...")\n    shutil.rmtree(test_dir)\n    for f in ["test_harvest.db", "test_harvest.log", "last_harvest.json"]:\n        if os.path.exists(f): os.remove(f)\n'

with open(r'D:\AI\tools\agent\harvest.py', 'w', encoding='utf-8') as f_out:
    f_out.write(part1 + part2)
print('harvest.py assembled successfully')